import asyncio,json,pathlib
from playwright.async_api import async_playwright
R=pathlib.Path('/workspace/ryderesolve-video-v2/video');store={k:json.loads((R/'demo-trips.json').read_text()) for k in ['change-rider-key','change-driver-key']}
async def m():
 async with async_playwright() as p:
  b=await p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=await b.new_context(viewport={'width':1920,'height':2000},device_scale_factor=2);await ctx.add_init_script('localStorage.setItem("ryderesolve_trips_v1",'+json.dumps(json.dumps(store))+');');pg=await ctx.new_page()
  async def phone(n):
   await pg.wait_for_timeout(500);await pg.evaluate('window.scrollTo(0,0)');await pg.locator('.app-shell').screenshot(path=str(R/'public/textures'/(n+'-phone.png')))
  await pg.goto('http://localhost:3001/rider');await pg.get_by_label('Demo passcode').fill('change-rider-key');await pg.get_by_role('button',name='Connect',exact=True).click();await pg.get_by_role('button',name='Trips',exact=True).click();await pg.get_by_role('button').filter(has_text='DEMO-DISP-003').click();await phone('rider-trip');await pg.get_by_role('button',name='Report issue',exact=True).click();await pg.locator('.app-form select').first.select_option('other');await pg.locator('textarea').fill('A charge appeared after my trip and I am unsure which category applies. Please review.');await pg.locator('input[type=number]').fill('4.50');await phone('rider-report');print('Selected trip label:',await pg.locator('.app-form select').nth(1).locator('option:checked').inner_text());print('Other help:',await pg.locator('.app-form .alert').inner_text())
  await pg.goto('http://localhost:3001/driver');await pg.get_by_label('Demo passcode').fill('change-driver-key');await pg.get_by_role('button',name='Connect',exact=True).click();await pg.get_by_role('button').filter(has_text='DEMO-DRIVER-CLARIFY').first.click();await phone('driver-clarification')
  await ctx.close();ctx=await b.new_context(viewport={'width':1920,'height':1080},device_scale_factor=2);pg=await ctx.new_page();await pg.goto('http://localhost:3001/reviewer');await pg.get_by_label('Demo passcode').fill('change-reviewer-key');await pg.get_by_role('button',name='Connect',exact=True).click();await pg.get_by_role('button').filter(has_text='DISP-003').click();await pg.get_by_role('tab').filter(has_text='Agent Findings').click();await pg.wait_for_timeout(600);await pg.screenshot(path=str(R/'public/textures/fare-agents.png'),full_page=True);print('Mode labels:',await pg.locator('.agent-mode').all_text_contents());await b.close()
asyncio.run(m())
